var calc_output = [];

var is = parseFloat(is);
var rr = parseFloat(rr);
var nps = parseFloat(nps);
var cough = parseFloat(cough);

var score = is + rr + nps + cough;

var risk;
if (score == 0) {
    risk = 'Low';
} else if (score <= 2) {
    risk = 'Intermediate';
} else if (score <= 4) {
    risk = 'High';
}

calc_output.push({
    name: 'mini',
    value: score,
    value_text: 'points',
    message: risk + ' risk of ≥1 adverse outcome'
});
calc_output.push({
    name: '10486_SCARF Score_result',
    value: score,
    value_text: 'points',
    message: 'SCARF Score'
});
calc_output.push({
    name: '10486_SCARF Score_interpretation',
    value: risk,
    value_text: 'risk',
    message: 'Risk of ≥1 adverse outcome'
});
